    var_visibleHome,
    false
);
UpdateContext(
    {
        var_visibleInspPatiocad: true,
        var_visibleInspPatiocad1: true,
        var_visibleInspPatiocad2: false,
        var_visibleInspPatiocadMenu: false,
        Var_IDinspTPS: GalleryInspTPSListagem.Selected.ID,
        var_acao: "Editar"
    }
);
EditForm(FormInspTPS)

Set(
    var_visibleHome,
    false
);
UpdateContext(
    {
        var_visibleRelatorio: true,
        Var_InspRelatorios: GalleryInspTPSListagem.Selected
    }
);
Set(
    var_inspRelatorio,
    Blank()
);
ClearCollect(
    col_relatorioPatioConforme,
    col_inspTPSmenu
);
Clear(col_relatorioPatioNaoConforme);
//Adiciona as não conformidades em uma coleção
ForAll(
    col_inspTPSmenu As MENU,
    ForAll(
        Filter(
            tbl_inspTPSitens,
            ID_insp = Var_InspRelatorios.ID
        ) As ITEM,
        If(
            MENU.ID = ITEM.'ID_item (ID_item0)',
            Collect(
                col_relatorioPatioNaoConforme,
                ITEM
            );
            RemoveIf(//Remove os itens 'não conformes' da coleção de itens 'conformes'
                col_relatorioPatioConforme,
                ID = ITEM.'ID_item (ID_item0)'
            )
        )
    )
)

Set(
    var_visibleHome,
    false
);
UpdateContext(
    {
        var_visibleExcluir: true,
        var_itemExluir: GalleryInspTPSListagem.Selected
    }
)

Switch(
    true,
    var_visibleInspPatiocad2,
    UpdateContext(
        {
            var_visibleInspPatiocad2: false,
            var_visibleInspPatiocadMenu: true
        }
    ),
    var_visibleInspPatiocadMenu,
    UpdateContext(
        {
            var_visibleInspPatiocadMenu: false,
            var_visibleInspPatiocad1: true,
            var_acao: "Finalizar"
        }
    ),
    var_visibleInspPatiocad1,
    UpdateContext(
        {
            var_visibleInspPatiocad1: false,
            var_visibleInspPatiocad: false,
            var_visibleInspPatio: true
        }
    );
    Set(
        var_visibleHome,
        true
    )
)

If(
    var_acao = "Cadastrar",
    Patch(
        tbl_inspTPS,
        Self.LastSubmit,
        {Protocolo: varIATAUser & "-" & "INSP-TPS" & "-" & Self.LastSubmit.ID}
    );
    UpdateContext(
        {
            Var_IDinspTPS: Self.LastSubmit.ID,
            var_visibleInspPatiocad1: false,
            var_visibleInspPatiocadMenu: true,
            var_visibleInspecaoCad3: false
        }
    ),
    Set(
        var_visibleHome,
        true
    );
    UpdateContext(
        {
            var_visibleInspPatio: true,
            var_visibleInspPatiocad: false,
            var_visibleInspPatiocad1: false,
            var_visibleInspPatiocadMenu: false,
            var_visibleInspecaoCad3: false
        }
    )
)

UpdateContext({var_visibleExcluirResumo: false});
Remove(
    tbl_inspTPSitens,
    var_IDInspTPSitem
);
Notify(
    "Item excluido com sucesso",
    NotificationType.Success
)

Patch(
    tbl_inspTPSitens,
    Self.LastSubmit,
    {Protocolo: varIATAUser & "-" & "INSP-TPS-ITEM" & "-" & Self.LastSubmit.ID}
);
UpdateContext(
    {
        var_visibleInspPatiocad2: false,
        var_visibleInspPatiocadMenu: true
    }
);
Notify(
    "Não conformidade salvo com sucesso!",
    NotificationType.Success
);
ResetForm(Self)

UpdateContext(
    {
        varLocal: Self.Text,
        varCategoria: "0",
        varSubCategoria: "0",
        varItem: "0"
    }
)

UpdateContext(
    {
        varLocal: Self.Text,
        varCategoria: "0",
        varSubCategoria: "0",
        varItem: "0"
    }
)

UpdateContext(
    {
        varLocal: Self.Text,
        varCategoria: "0",
        varSubCategoria: "0",
        varItem: "0"
    }
)

UpdateContext(
    {
        varLocal: Self.Text,
        varCategoria: "0",
        varSubCategoria: "0",
        varItem: "0"
    }
)

true

