    {
        var_visibleInspPatiocad2: true,
        var_visibleInspPatiocadMenu: false,
        varItem: ThisItem.item,
        varItemId: ThisItem.ID
    }
);
NewForm(FormInspPatioitens)

true

/*
If(
    varMenu = "0" And !IsBlank(ThisItem.btn1);
    true;
    If(
        varMenu = ThisItem.btn1;
        true
    )
)*/

UpdateContext(
