    SubmitForm(FormInspTPS),
    UpdateContext(
        {
            var_visibleInspPatiocad1: false,
            var_visibleInspPatiocadMenu: true,
            var_visibleInspPatiocad3: false
        }
    ),
    UpdateContext(
        {
            var_visibleInspPatiocad1: false,
            var_visibleInspPatiocadMenu: true,
            var_visibleInspecaoCad3: false
        }
    )
)

Set(
    var_visibleHome,
    true
);
UpdateContext(
    {
        var_visibleExcluir: false,
        var_visibleInspPatio: true
    }
)

Set(
    var_visibleHome,
    true
);
UpdateContext(
    {
        var_visibleExcluir: false,
        var_visibleInspPatio: true
    }
);
Concurrent(
    RemoveIf(
        tbl_inspTPSitens,
        ID_insp = var_itemExluir.ID
    ),
    RemoveIf(
        tbl_inspTPS,
        ID = var_itemExluir.ID
    )
);
Notify(
    "A inspeção e todos os Itens vinculados foram excluidos com sucesso!",
    NotificationType.Success
)

Set(
    var_visibleHome,
    true
);
UpdateContext(
    {
        var_visibleInspTpsgerNaoConf: false,
        var_visibleInspPatio: true
    }
)

ForAll(
    Distinct(
        Filter(
            colAeros,
            Bloco = cmbHomeBloco_7.Selected.Value
        ),
        Aeroporto
    ),
    {Result: ThisRecord.Value}
)

Reset(cmbHomeBloco_7);
Reset(cmbHomeAeroporto_7);
Reset(dtpHomeDtfInicio_7);
Reset(dtpHomeDtfTermino_7);
Reset(cmbApontStatus_3);
Reset(cmbHomeLocal_2);
Reset(cmbHomeLocal_2);
Reset(cmbHomeItem_4);
